contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(address _asset, uint256 _kink, uint256 _slope0, uint256 _slope1) public payable {
        require(_asset != address(0));
        require(_kink > 0 && _kink < 1e27);

        c.setSlopes(_asset, IVaultAdapter.SlopeData(_kink, _slope0, _slope1));

        // Fresh storage: utilizationData.index and multiplier are 0, lastUpdate = 0,
        // so rate() should settle on utilization = 0 (from IVault), elapsed = 0.
        // _applySlopes then: since utilization (0) <= kink, multiplier branch:
        // multiplier = 0 * 1e27 / (...) = 0, and clamp only if < minMultiplier.
        // With minMultiplier default 0, multiplier stays 0, so interestRate = 0.
        c.rate(address(this), _asset);

        IVaultAdapter.SlopeData memory expected = IVaultAdapter.SlopeData(_kink, _slope0, _slope1);
        IVaultAdapter.SlopeData memory stored = c.slopeData(_asset); // may not be visible; guarded below

        assert(stored.kink == expected.kink && stored.slope0 == expected.slope0 && stored.slope1 == expected.slope1);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(address _vault, address _asset, uint256 _kink, uint256 _slope0, uint256 _slope1) public payable {
        require(_vault != address(0) && _asset != address(0));
        require(_kink > 0 && _kink < 1e27);

        c.setSlopes(_asset, IVaultAdapter.SlopeData(_kink, _slope0, _slope1));

        uint256 beforeUtil = IVault(_vault).utilization(_asset);
        uint256 beforeIndex = IVault(_vault).currentUtilizationIndex(_asset);

        uint256 r;
        bool reverted;
        try c.rate(_vault, _asset) returns (uint256 v) { r = v; reverted = false; } catch { reverted = true; }

        // General rule: after a valid setSlopes, the first live rate() call on the fresh
        // utilization storage must succeed and reflect the slopes only through the
        // utilization snapshot returned by the vault, i.e. it must equal the value obtained
        // by applying the supplied slopes to the current vault utilization.
        uint256 expected;
        if (beforeUtil > _kink) {
            uint256 excess = beforeUtil - _kink;
            expected = _slope0 + (_slope1 * excess / 1e27);
        } else {
            expected = _slope0 * beforeUtil / _kink;
        }

        assert(!reverted && r == expected);
    }

    receive() external payable {}
}

