    }

    function run(
        address accessControl,
        address assetA,
        address assetB,
        uint256 kinkA,
        uint256 slope0A,
        uint256 slope1A,
        uint256 kinkB,
        uint256 slope0B,
        uint256 slope1B,
        uint256 maxMultiplier,
