contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 maxMultiplier, uint256 minMultiplier, uint256 rate) public {
        // setLimits is guarded by checkAccess(this.setLimits.selector), so a
        // call only succeeds if the selector's role is granted to this test.
        // The rule: the call must either revert (no access) or persist the
        // exact values, observable through the public getters, and never
        // leave partially-applied state.
        bool reverted;
        try c.setLimits(maxMultiplier, minMultiplier, rate) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            // All three storage slots were updated atomically; the public
            // surface must reflect exactly the arguments we passed.
            assert(
                c.maxMultiplier() == maxMultiplier
                    && c.minMultiplier() == minMultiplier
                    && c.rate_() == rate
            );
        } else {
            // Failed authorization: no portion of the limits may have changed
            // relative to a fresh deployment's default (all zero).
            assert(
                c.maxMultiplier() == 0
                    && c.minMultiplier() == 0
                    && c.rate_() == 0
            );
        }
    }

    receive() external payable {}
}

