    function run(uint256 maxMultiplier, uint256 minMultiplier, uint256 rate) public {
        bool reverted;
        try c.setLimits(maxMultiplier, minMultiplier, rate) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            // If the call succeeded, the limits were accepted and persisted.
            // We can only observe via the public surface: setLimits must have succeeded,
            // so the access check passed and the values were stored.
            // Since there is no getter for limits, we verify that a subsequent call
