                secondReverted = false;
            } catch {
                secondReverted = true;
            }
            assert(!secondReverted);
        } else {
            // If the call reverted, it must have been an access denial, and the state
            // must remain unchanged. Since no getter exists, we assert that a second
            // attempt with the same parameters also reverts (consistency of access).
            bool secondReverted;
            try c.setLimits(maxMultiplier, minMultiplier, rate) {
                secondReverted = false;
            } catch {
                secondReverted = true;
            }
            assert(secondReverted);
        }
    }

    receive() external payable {}
}

